# Hand edits to the stubs, applied after consulo-internal/remap/genstub.py when regenerating from scratch
cd /run/media/vistall/repositories/JetBrains/kotlin/consulo-internal/intellij-stubs/src/main/java/com/intellij/psi
rm -f util/MethodSignatureBackedByPsiMethod.java  # a class in IntelliJ and Consulo, generated by genstub.py
sed -i 's/^public interface PsiModifierListOwner extends com.intellij.psi.PsiElement {/public interface PsiModifierListOwner extends com.intellij.psi.PsiElement, com.intellij.lang.jvm.JvmModifiersOwner {/' PsiModifierListOwner.java
sed -i 's#^    java.util.List<com.intellij.psi.PsiMethod> findSuperMethods(com.intellij.psi.PsiClass parentClass, boolean checkAccess);#    default java.util.List<com.intellij.psi.PsiMethod> findSuperMethods(com.intellij.psi.PsiClass parentClass, boolean checkAccess) { return java.util.Collections.emptyList(); }#' PsiMethod.java
sed -i 's#^    com.intellij.psi.tree.IElementType getLiteralElementType();#    default com.intellij.psi.tree.IElementType getLiteralElementType() { return null; }#' PsiLiteralExpression.java
sed -i 's#^    com.intellij.psi.PsiAnnotationOwner getAnnotationOwnerPsi();#    default com.intellij.psi.PsiAnnotationOwner getAnnotationOwnerPsi() { return null; }#' PsiTypeParameter.java
sed -i 's#^    com.intellij.psi.PsiIdentifier getReferenceNameElement();#    com.intellij.psi.PsiElement getReferenceNameElement();#' PsiReferenceExpression.java
sed -i 's/^public abstract class PsiArrayType /public class PsiArrayType /' PsiArrayType.java
sed -i 's/^public abstract class PsiEllipsisType /public class PsiEllipsisType /' PsiEllipsisType.java
python3 - <<'PY'
def add(p, member):
    s = open(p).read()
    if member.split('(')[0].split()[-1] in s and 'JAVA_LANG_ANNOTATION' not in member:
        return
    i = s.rstrip().rfind('}')
    open(p, 'w').write(s[:i] + member + '\n' + s[i:])
add('CommonClassNames.java', '    String JAVA_LANG_ANNOTATION_RETENTION = "java.lang.annotation.Retention";\n    String JAVA_LANG_ANNOTATION_TARGET = "java.lang.annotation.Target";')
add('PsiField.java', '    default boolean isVisibilitySupported() { return true; }')
add('util/ClassUtil.java', '    public static String getAsmMethodSignature(com.intellij.psi.PsiMethod method) { return null; }')
PY
